from email.utils import formataddr, parseaddr
from pathlib import Path

from decouple import Csv, config


def _load_env_local() -> None:
    """Merge .env.local (gitignored, generated by `vercel env pull` from the
    Supabase integration) into the process environment so decouple's config()
    picks it up locally. In production, Vercel injects these same STORAGE_*
    vars directly into the environment and no .env.local file is deployed, so
    this is a local-dev-only convenience, not a second source of truth."""
    import os

    env_local_path = Path(__file__).resolve().parent.parent / ".env.local"
    if not env_local_path.exists():
        return
    for line in env_local_path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


_load_env_local()

