# --------------------------------------------------------------------------
# DATABASE (Supabase Postgres in production)
# --------------------------------------------------------------------------
# Pooled (pgbouncer, transaction mode) connection -- used for runtime app traffic
# under Vercel's serverless model, where many short-lived connections would
# otherwise exhaust Postgres's max_connections.
DATABASE_URL = config("STORAGE_POSTGRES_URL", default="")
# Direct (non-pooled) connection -- used for migrate/admin commands, since DDL
# is unreliable behind a transaction-mode pooler.
DATABASE_URL_DIRECT = config("STORAGE_POSTGRES_URL_NON_POOLING", default="")

